 * The highest number the project has ever issued (ADR 0011). The counter row
 * is what remembers numbers whose issue has since moved away; the rows are
 * still consulted so a project populated before the counter existed, or
 * outside `insertIssue` (the seed, an import), is never numbered from too low.
 * Archived issues keep their number, so the max is taken over every row.
 */
function highestIssuedNumber(
  db: Executor,
  orgId: OrgId,
  projectId: ProjectId,
): number {
  const counter = db
    .select({ value: issueNumberCounters.lastNumber })
    .from(issueNumberCounters)
    .where(
      and(
        orgPredicate(issueNumberCounters.orgId, orgId),
        eq(issueNumberCounters.projectId, projectId),
