function rememberIssuedNumber(
  db: Executor,
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): void {
  db.insert(issueNumberCounters)
    .values({ projectId, orgId, lastNumber: issueNumber })
    .onConflictDoUpdate({
      target: issueNumberCounters.projectId,
      set: {
        lastNumber: sql`max(${issueNumberCounters.lastNumber}, excluded.last_number)`,
      },
    })
    .run();
}

