sub(p, '''/** Cascade behind `ProjectService.archiveProject`; returns the row count. */''', '''/**
 * Moves an issue into another project of the same org (ADR 0011), as one
 * transaction:
 *
 *  - the number it carried is retired in the project it leaves,
 *  - it takes the next number of the project it joins, allocated exactly as
 *    `nextIssueNumber` would for a new issue there,
 *  - the search document that denormalises its project follows it, so a
 *    project-scoped search never sees the issue in two places or in neither.
 *
 * Nothing else on the row changes, and neither do its labels, comments,
 * attachments, parent or children. A same-project "move" returns the row
 * untouched.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
): Promise<Issue> {
  const row = getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();

    if (!current) throw new Error(`Issue ${issueId} not found`);
    if (current.projectId === toProjectId) return current;

    const fromProjectId = current.projectId as ProjectId;
    rememberIssuedNumber(
      tx,
      orgId,
      fromProjectId,
      highestIssuedNumber(tx, orgId, fromProjectId),
    );

    const issueNumber = highestIssuedNumber(tx, orgId, toProjectId) + 1;
    rememberIssuedNumber(tx, orgId, toProjectId, issueNumber);

    const moved = tx
      .update(issues)
      .set({
        projectId: toProjectId,
        number: issueNumber,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning()
      .get();

    tx.update(searchIndex)
      .set({ projectId: toProjectId })
      .where(
        and(
          orgPredicate(searchIndex.orgId, orgId),
          eq(searchIndex.subjectKind, "issue"),
          eq(searchIndex.subjectId, issueId),
        ),
      )
      .run();

    return moved;
  });

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

