import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { activityFilterSchema } from "@/schemas/activity";
import { moveIssueToProjectSchema } from "@/schemas/issue";
import { NotFoundError } from "@/server/services/_support";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Project } from "@/types/project";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let projectCount = 0;
const detachers: Unsubscribe[] = [];
const listeners: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function newProject(owner: Tenant = tenant): Promise<Project> {
  projectCount += 1;
  return projectRepo.insertProject({
    orgId: owner.org.id,
    name: `Target ${projectCount}`,
    slug: `target-${projectCount}`,
    key: `T${projectCount}`,
    description: null,
    visibility: "org",
    leadId: owner.userIds.owner,
    color: "#6366f1",
    targetDate: null,
  });
}

async function newIssue(project: Project, title: string) {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, project.id, { title }),
  );
}

function move(issueId: string, toProjectId: string, actor = tenant.actors.member) {
  return issueService.moveIssueToProject(
    actor,
    moveIssueToProjectSchema.parse({ orgId: tenant.org.id, issueId, toProjectId }),
  );
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("movesvc", "growth");
  other = await createTenant("moveother", "growth");
  listeners.push(registerActivityListeners(), searchService.registerSearchListeners());
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  for (const off of listeners) off();
  cleanup();
});

describe("moveIssueToProject — the issue", () => {
  it("joins the target under its next number and keeps everything else", async () => {
    const source = await newProject();
    const target = await newProject();
    await newIssue(target, "Already here 1");
    await newIssue(target, "Already here 2");

    const label = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "moves-along",
      color: "#ef4444",
      description: null,
    });
    const parent = await newIssue(source, "Parent stays");
    const issue = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, source.id, {
        title: "Filed in the wrong place",
        assigneeId: tenant.userIds.admin,
      }),
      description: "Body",
      status: "in_progress",
      priority: "high",
      estimate: 5,
      parentId: parent.id,
      labelIds: [label.id],
    });
    const child = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, source.id, { title: "Child stays" }),
      parentId: issue.id,
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Comes along",
      parentId: null,
      mentionedUserIds: [],
    });
    const before = await issueRepo.findIssueById(tenant.org.id, issue.id);

    const moved = await move(issue.id, target.id);

    expect(moved).toEqual({
      ...before,
      projectId: target.id,
      number: 3,
      updatedAt: expect.any(String),
    });
    expect(moved.labelIds).toEqual([label.id]);
    await expect(issueRepo.findIssueById(tenant.org.id, issue.id)).resolves.toEqual(moved);

    await expect(commentRepo.countComments(tenant.org.id, issue.id)).resolves.toBe(1);
    await expect(attachmentRepo.listAttachments(tenant.org.id, issue.id)).resolves.toEqual([]);

    // Links are left alone: the parent and the child stay where they were.
    await expect(issueRepo.findIssueById(tenant.org.id, parent.id)).resolves.toMatchObject({
      projectId: source.id,
      number: parent.number,
    });
    await expect(issueRepo.findIssueById(tenant.org.id, child.id)).resolves.toMatchObject({
      projectId: source.id,
      parentId: issue.id,
    });
  });

  it("shows up on the target's board and list and leaves the source's", async () => {
    const source = await newProject();
    const target = await newProject();
    const issue = await newIssue(source, "Board hopper");

    await move(issue.id, target.id);

    const boardIds = async (project: Project) =>
      (await issueService.getBoard(tenant.actors.member, tenant.org.id, project.id)).flatMap(
        (column) => column.issues.map((row) => row.id),
      );
    const listIds = async (project: Project) =>
      (
        await issueService.listIssues(tenant.actors.member, {
          orgId: tenant.org.id,
          projectId: project.id,
          limit: 25,
          cursor: null,
        })
      ).items.map((row) => row.id);

    await expect(boardIds(source)).resolves.toEqual([]);
    await expect(boardIds(target)).resolves.toEqual([issue.id]);
    await expect(listIds(source)).resolves.toEqual([]);
    await expect(listIds(target)).resolves.toEqual([issue.id]);
  });

  it("does nothing when the target is the project it is already in", async () => {
    const source = await newProject();
    const issue = await newIssue(source, "Staying put");
    const before = await issueRepo.findIssueById(tenant.org.id, issue.id);
    const moved = capture("issue.moved");
    const updated = capture("issue.updated");

    await expect(move(issue.id, source.id)).resolves.toEqual(before);

    await expect(issueRepo.findIssueById(tenant.org.id, issue.id)).resolves.toEqual(before);
    await expect(issueRepo.nextIssueNumber(tenant.org.id, source.id)).resolves.toBe(2);
    expect(moved).toHaveLength(0);
    expect(updated).toHaveLength(0);
  });
});

describe("moveIssueToProject — numbering", () => {
  it("never reissues a number in the project the issue left", async () => {
    const source = await newProject();
    const target = await newProject();
    await newIssue(source, "One");
    await newIssue(source, "Two");
    const three = await newIssue(source, "Three");

    await move(three.id, target.id);

    const next = await newIssue(source, "Four");
    expect(next.number).toBe(4);
  });

  it("retires numbers across a move away and back", async () => {
    const source = await newProject();
    const target = await newProject();
    const issue = await newIssue(source, "Round trip");
    expect(issue.number).toBe(1);

    const away = await move(issue.id, target.id);
    expect(away.number).toBe(1);

    const back = await move(issue.id, source.id);
    expect(back.number).toBe(2);

    expect((await newIssue(source, "After")).number).toBe(3);
    expect((await newIssue(target, "After")).number).toBe(2);
  });

  it("retires the number of an issue that was not created through the allocator's counter", async () => {
    const source = await newProject();
    const target = await newProject();
    const seeded = await issueRepo.insertIssue(
      issueInput(tenant.org.id, source.id, { title: "Seeded high" }),
      tenant.userIds.member,
      41,
    );

    await move(seeded.id, target.id);

    await expect(issueRepo.nextIssueNumber(tenant.org.id, source.id)).resolves.toBe(42);
  });
});

describe("moveIssueToProject — refusals change nothing", () => {
  it("needs issue:update on the issue", async () => {
    const source = await newProject();
    const target = await newProject();
    const issue = await newIssue(source, "Not yours");

    await expect(move(issue.id, target.id, tenant.actors.viewer)).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
  });

  it("needs issue:create in the target even for someone who may edit the issue", async () => {
    const source = await newProject();
    const target = await newProject();
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, source.id, {
        title: "Assigned to a viewer",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    const before = await issueRepo.findIssueById(tenant.org.id, issue.id);
    const seen = capture("issue.moved");

    // The assignee may edit it…
    await issueService.updateIssue(tenant.actors.viewer, {
      orgId: tenant.org.id,
      issueId: issue.id,
      priority: "low",
    });
    // …but may not create issues in the target.
    const error: unknown = await move(issue.id, target.id, tenant.actors.viewer).catch(
