    await expect(
      issueService.moveIssueToProject(free.actors.member, {
        orgId: free.org.id,
        issueId: issue.id,
        toProjectId: full.id,
      }),
    ).rejects.toThrow(/allows no more issues/);

    expect(seen).toHaveLength(0);
    await expect(issueRepo.findIssueById(free.org.id, issue.id)).resolves.toEqual(issue);
    await expect(issueRepo.countIssues(free.org.id, full.id)).resolves.toBe(100);
    await expect(issueRepo.nextIssueNumber(free.org.id, full.id)).resolves.toBe(101);
  });

  it("refuses an archived issue, an archived target and a target in another workspace", async () => {
    const source = await newProject();
    const target = await newProject();
    const archivedTarget = await newProject();
    await projectRepo.archiveProject(tenant.org.id, archivedTarget.id);
    const foreign = await newProject(other);

    const live = await newIssue(source, "Live");
    const archived = await newIssue(source, "Archived");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    await expect(move(archived.id, target.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(move(live.id, archivedTarget.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(move(live.id, foreign.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.moveIssueToProject(other.actors.owner, {
        orgId: tenant.org.id,
        issueId: live.id,
        toProjectId: target.id,
      }),
