  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, project.id, { title }),
  );
}

function move(issueId: string, toProjectId: string, actor = tenant.actors.member) {
  return issueService.moveIssueToProject(
    actor,
    moveIssueToProjectSchema.parse({ orgId: tenant.org.id, issueId, toProjectId }),
  );
}

