    await expect(issueRepo.nextIssueNumber(free.org.id, full.id)).resolves.toBe(101);
  });

  it("refuses an archived issue, an archived target and a target in another workspace", async () => {
    const source = await newProject();
    const target = await newProject();
    const archivedTarget = await newProject();
    await projectRepo.archiveProject(tenant.org.id, archivedTarget.id);
    const foreign = await newProject(other);

    const live = await newIssue(source, "Live");
    const archived = await newIssue(source, "Archived");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    await expect(move(archived.id, target.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(move(live.id, archivedTarget.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(move(live.id, foreign.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.moveIssueToProject(other.actors.owner, {
        orgId: tenant.org.id,
        issueId: live.id,
        toProjectId: target.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(issueRepo.findIssueById(tenant.org.id, live.id)).resolves.toMatchObject({
      projectId: source.id,
      number: live.number,
    });
  });
});

describe("moveIssueToProject — what reacts", () => {
  it("publishes exactly one issue.moved and nothing else", async () => {
    const source = await newProject();
    const target = await newProject();
    const issue = await newIssue(source, "Announce me");

    const moved = capture("issue.moved");
    const others = [
      capture("issue.created"),
      capture("issue.updated"),
      capture("issue.archived"),
      capture("issue.status_changed"),
      capture("issue.assigned"),
    ];

    await move(issue.id, target.id, tenant.actors.admin);

    expect(moved).toHaveLength(1);
    expect(moved[0]).toEqual({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      occurredAt: expect.any(String),
      issueId: issue.id,
      fromProjectId: source.id,
      toProjectId: target.id,
      fromNumber: 1,
      toNumber: 1,
    });
    expect(others.flat()).toHaveLength(0);
  });

  it("records the move once under the target and leaves earlier entries alone", async () => {
    const source = await newProject();
    const target = await newProject();
    await newIssue(target, "Occupies #1");
    const issue = await newIssue(source, "Audited");

    await move(issue.id, target.id);

    const history = await activityRepo.listActivityForSubject(tenant.org.id, "issue", issue.id);
    const created = history.filter((event) => event.action === "issue.created");
    const moves = history.filter((event) => event.action === "issue.moved");

    expect(created).toHaveLength(1);
    expect(created[0]?.projectId).toBe(source.id);
    expect(moves).toHaveLength(1);
    expect(moves[0]).toMatchObject({
      actorId: tenant.userIds.member,
      subjectKind: "issue",
      subjectId: issue.id,
      projectId: target.id,
      metadata: {
        fromProjectId: source.id,
        toProjectId: target.id,
        fromNumber: 1,
        toNumber: 2,
      },
    });

    const filter = activityFilterSchema.parse({
      orgId: tenant.org.id,
      action: ["issue.moved"],
      projectId: target.id,
    });
    const page = await activityRepo.listActivity(filter);
    expect(page.items.map((event) => event.id)).toEqual([moves[0]?.id]);
  });

  it("is found by a search inside the target and not inside the source", async () => {
    const source = await newProject();
    const target = await newProject();
    const issue = await newIssue(source, "Quebec relocation marker");

    const hits = async (projectId: Project["id"]) =>
      (
        await searchService.search(tenant.actors.member, {
          orgId: tenant.org.id,
          q: "Quebec relocation",
          kinds: ["issue"],
          projectId,
          limit: 25,
          cursor: null,
        })
      ).items.map((hit) => hit.id);

    await expect(hits(source.id)).resolves.toEqual([issue.id]);

    await move(issue.id, target.id);

    await expect(hits(source.id)).resolves.toEqual([]);
    await expect(hits(target.id)).resolves.toEqual([issue.id]);
  });
});

